var nums = [1,2,3,4,5];
var evens = nums.filter(function(n){ return n % 2 === 0; });
var doubled = evens.map(function(n){ return n * 2; });
var sum = doubled.reduce(function(acc, n){ return acc + n; }, 0);
console.log('filter:', evens.join(','));
console.log('map:', doubled.join(','));
console.log('reduce sum:', sum);
console.log('every >0:', nums.every(function(n){ return n > 0; }));
console.log('some >4:', nums.some(function(n){ return n > 4; }));
